

import { Box, Checkbox, FormControlLabel, Typography, Link, TextField, InputAdornment, IconButton, Button, CircularProgress } from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import BaseCard from '../../../components/Cards/Card';
import { useTheme } from "@mui/material/styles";
import useMediaQuery from '@mui/material/useMediaQuery';
import { useFormik } from 'formik';
import { toast } from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { loginAdmin, clearError } from '../../../Redux/Slices/AuthSlice';

const Login = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();
  const dispatch = useDispatch();
  
  const { loading, error } = useSelector((state) => state.auth);
  
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem("adminCredentials");
    if (saved) {
      const { email, password } = JSON.parse(saved);
      formik.setFieldValue("email", email);
      formik.setFieldValue("password", password);
      setRememberMe(true);
    }
    return () => {
      dispatch(clearError());
    };
  }, [dispatch]);

  const validate = (values) => {
    const errors = {};
    if (!values.email) {
      errors.email = "Email is required";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
      errors.email = "Email is invalid";
    }
    if (!values.password) {
      errors.password = "Password is required";
    }
    return errors;
  };

  const formik = useFormik({
    initialValues: { email: '', password: '' },
    validate,
    onSubmit: async (values) => {
      const action = await dispatch(loginAdmin({ 
        email: values.email, 
        password: values.password, 
        rememberMe 
      }));

      if (loginAdmin.fulfilled.match(action)) {
       
        setTimeout(() => navigate("/dashboard"), 1000);
      } else {
        toast.error(action.payload || "Login failed");
      }
    }
  });

  const handleForget = () => navigate("/forget-password");

  return (
    <Box sx={{ width: '100%', display: 'flex', justifyContent: 'center' }}>
      <BaseCard
        maxWidth={isMobile ? '100%' : 400}
        sx={{
          width: isMobile ? '100%' : 400,
          p: 4,
          backgroundColor: "rgba(0, 0, 0, 0.7)", // Semi-transparent black
          backdropFilter: 'blur(16px)', // Glassmorphism effect
          border: "1px solid #4CC66E", // Premium green full border
          borderRadius: "16px",
          boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.8)',
        }}
      >
          <form onSubmit={formik.handleSubmit}>
            <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
              {/* Logo Section */}
              <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 1 }}>
                <img src="/favicon.svg" style={{ width: 100, height: 100, objectFit: "contain" }} alt="Logo" />
               
              </Box>

              <Box sx={{ textAlign: 'center' }}>
                <Typography variant="h5" sx={{ color: 'white', mb: 0.5 }}>
                  Welcome Back
                </Typography>
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                  Login to your account
                </Typography>
              </Box>

              <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
                <Typography variant="body2" sx={{ color: 'white' }}>Email</Typography>
                <TextField
                  fullWidth
                  name="email"
                  placeholder="john@gmail.com"
                  value={formik.values.email}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  error={formik.submitCount > 0 && Boolean(formik.errors.email)}
                  helperText={formik.submitCount > 0 && formik.errors.email}
                />
              </Box>

              <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
                <Typography variant="body2" sx={{ color: 'white' }}>Password</Typography>
                <TextField
                  fullWidth
                  name="password"
                  type={showPassword ? 'text' : 'password'}
                  placeholder="********"
                  value={formik.values.password}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  error={formik.submitCount > 0 && Boolean(formik.errors.password)}
                  helperText={formik.submitCount > 0 && formik.errors.password}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          onClick={() => setShowPassword(!showPassword)}
                          edge="end"
                          sx={{ color: 'text.secondary' }}
                        >
                          {showPassword ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                />
              </Box>

              <Box sx={{ 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center", 
                flexWrap: 'nowrap',
                gap: 1
              }}>
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={rememberMe}
                      onChange={(e) => setRememberMe(e.target.checked)}
                      color="primary"
                      size="small"
                    />
                  }
                  label={
                    <Typography variant="body2" sx={{ color: 'white', whiteSpace: 'nowrap' }}>
                      Remember me
                    </Typography>
                  }
                />
                <Link
                  component="button"
                  variant="body2"
                  onClick={handleForget}
                  sx={{
                    color: 'primary.main',
                    textDecoration: 'none',
                    fontWeight: 600,
                    cursor: "pointer",
                    '&:hover': { textDecoration: 'underline' }
                  }}
                >
                  Forgot Password
                </Link>
              </Box>

              <Button
                variant="contained"
                type="submit"
                disabled={loading}
                startIcon={loading && <CircularProgress size={20} color="inherit" />}
              >
               Login
              </Button>
            </Box>
          </form>
        </BaseCard>
      </Box>
  );
};


export default Login;









